def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]
    oppseq = [b for _, b in history]
    opp_c = sum(1 for b in oppseq if b == 'C')
    opp_d = n - opp_c
    d10 = sum(1 for b in oppseq[-10:] if b == 'D')
    d5 = sum(1 for b in oppseq[-5:] if b == 'D')

    c_streak = 0
    for b in reversed(oppseq):
        if b == 'C':
            c_streak += 1
        else:
            break

    d_streak = 0
    for b in reversed(oppseq):
        if b == 'D':
            d_streak += 1
        else:
            break

    # If the opponent has never defected, cooperate early, then test/exploit.
    # Against TFT-like opponents this costs only a short retaliation cycle.
    if opp_c == n:
        if n >= 25:
            return 'D'
        return 'C'

    # Continue exploiting a pushover: we defected last turn, they still cooperated,
    # and they have not defected recently or have a long C streak.
    if my_last == 'D' and opp_last == 'C':
        if d10 == 0 or c_streak >= 18:
            return 'D'

    # A few early defections followed by a long cooperation streak often indicates
    # an exploitable forgiving opponent. Probe once this streak becomes long.
    if 2 <= opp_d <= 5 and c_streak >= 18 and d10 == 0 and n >= 30:
        return 'D'

    # Simple periodic prediction: if the recent opponent sequence repeats with a
    # period and the next predicted move is D, defect to avoid being exploited.
    for p in range(2, 6):
        if n >= 2 * p:
            ok = True
            for i in range(p):
                if oppseq[n - 1 - i] != oppseq[n - 1 - p - i]:
                    ok = False
                    break
            if ok and oppseq[n - p] == 'D':
                return 'D'

    # Very hostile opponents: defect almost always, with rare probes.
    if opp_d * 10 >= 8 * n and d_streak >= 4:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Endgame defense: if the opponent has shown recent D in the last rounds,
    # lock in defense. The final round itself is handled above.
    if n >= 95 and (d5 >= 1 or opp_d >= 2):
        return 'D'

    if opp_last == 'D':
        if my_last == 'D':
            # After mutual D, break spirals if they have already returned to C.
            if c_streak >= 3:
                return 'C'

            # Otherwise punish hard defectors more, forgive conditional/nice ones.
            if opp_c == 0:
                p_c = 0.02 if d_streak >= 3 else 0.10
            elif d_streak <= 4:
                p_c = 0.25
            elif d_streak <= 8:
                p_c = 0.10
            else:
                p_c = 0.03

            if opp_d * 2 >= n and d10 >= 8:
                if p_c > 0.04:
                    p_c = 0.04

            if rng.random() < p_c:
                return 'C'
            return 'D'

        # If we provoked their D by defecting last turn while they cooperated,
        # return C to restore mutual cooperation against TFT-like players.
        if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'C':
            if opp_c * 3 >= 2 * n or opp_d * 10 <= 3 * n:
                return 'C'

        return 'D'

    # Opponent cooperated last move.
    if my_last == 'D':
        # If exploit mode above did not trigger, assume they may retaliate.
        return 'C'

    # Rare soft probe against very cooperative opponents in long games.
    if n >= 60 and d10 <= 1 and opp_c * 10 >= 9 * n and rng.random() < 0.08:
        return 'D'

    return 'C'
